-- Seed Exercise Library for Existing Coaches
-- Run this ONCE in your Supabase SQL Editor to add the default exercises
-- to all organizations that don't already have exercise library entries.
--
-- Safe to run multiple times — it skips orgs that already have exercises.

DO $$
DECLARE
  org RECORD;
BEGIN
  -- Loop through all organizations that have NO exercise library entries
  FOR org IN
    SELECT o.id, o.name
    FROM public.organizations o
    WHERE NOT EXISTS (
      SELECT 1 FROM public.templates t
      WHERE t.organization_id = o.id
        AND t.type = 'day'
        AND t.category = '__exercise_library__'
    )
  LOOP
    RAISE NOTICE 'Seeding exercises for org: % (%)', org.name, org.id;


  END LOOP;
END $$;

